{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Repeated testing is undocumented; this does not establish whether it occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "The tested system scored 70% in one reported run.",
          "reason": "One reported score cannot demonstrate consistency across runs."
        }
      ],
      "instrument_review": "EFPA sections 9.3 and 9.7 are interpreted as repeat-run consistency for an unchanged AI system. Relevant evidence is insufficient, corresponding to rating 0 rather than demonstrated inadequacy. Section 9.6 is inapplicable to exact-grid scoring without judgement."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly rules out repeated testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "No repeat-run evidence supports stability; this also does not demonstrate instability."
        }
      ],
      "instrument_review": "Under EFPA sections 9.3 and 9.7, reinterpreted for AI repeat runs, no consistency estimate is available. Rating 0 reflects insufficient evidence, despite explicit confirmation that repetition was not conducted."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "Repeated evaluations and matching conditions are explicitly reported."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The range meets the report's stated maximum of two percentage points."
        }
      ],
      "instrument_review": "EFPA sections 9.3 and 9.7 support considering these repeated runs as precision evidence. Stability is supported for this system and setup under the supplied definition. That definition is not an EFPA rating threshold, and these findings alone do not establish benchmark-wide reliability."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "The developers explicitly tested repeated runs under matching conditions."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed spread exceeds the stated stability limit of two percentage points."
        }
      ],
      "instrument_review": "EFPA sections 9.3 and 9.7 distinguish conducting a precision study from obtaining satisfactory results. These results demonstrate instability under the supplied definition for this setup. They provide adverse evidence rather than merely missing evidence."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation documentation supplies no evidence of repeated testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The new instructions add no findings about score consistency."
        }
      ],
      "instrument_review": "EFPA sections 6.3.8 and 9 address different matters: technical instructions and reliability evidence. Download and dependency instructions inform the former without resolving the latter. Repeat-run precision remains insufficiently documented, corresponding to rating 0."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A achieved the higher score on the evaluated puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The evidence does not establish an intelligence difference across domains."
        }
      ],
      "instrument_review": "EFPA sections 10.1 and 10.5 require evaluating the particular score interpretation. The observed comparison matches the stated narrow use. Broader intelligence claims lack supporting domain coverage and external evidence; absence of such evidence does not establish that the claims are false."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "The reported scores support A's better performance on these puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "Stating a broad intended use does not supply evidence for it."
        }
      ],
      "instrument_review": "EFPA sections 6.1, 10.1, 10.3 and 10.5 require evidence supporting the claimed interpretation. Cross-domain intelligence selection exceeds the supplied grid evidence. Validity for that intended use is insufficiently established, corresponding to 0 rather than proof of invalidity; as a critical quality, this triggers EFPA's restriction to research or exceptional expert use."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "No initial evidence links those scores to improved real workshop decisions."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "Random allocation, blinded correctness checks and an uncertainty interval above zero support better correctness with A in the studied setting."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Decision correctness findings do not establish an improvement in the unmeasured safety outcome."
        }
      ],
      "instrument_review": "EFPA sections 10.3.1.6, 10.3.2 and 10.5 distinguish test scores from evidence concerning practical outcomes. The later randomized trial supplies relevant correctness evidence for the stated workshop use. Its 120 inspectors must not be confused with a count of decisions; criterion reliability and broader generalisation remain unestablished. Safety requires separate evidence."
    }
  ],
  "closing_note": "No task instruction required clarification. The complete supplied EFPA model guided selection of relevant sections; full forms were explicitly unnecessary. AI systems replace human test takers only where stated, and repeat runs reinterpret human retesting. Human identity, disability accommodations, qualifications and debriefing questions are inapplicable to AI systems as human examinees; operator and stakeholder guidance may still apply. Probe labels are distinct from EFPA ratings. No aggregate quality score was calculated, and this simulation implies no EFPA endorsement."
}
